-- Read-only verification after 202611130001.
select 'Round-count column' as check_name,count(*)::text as actual,'1' as expected from information_schema.columns where table_schema='public' and table_name='workout_sections' and column_name='interval_rounds'
union all select 'Numeric scoring validator',count(*)::text,'1' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='save_workout_section' and p.prosrc like '%Tabata score must be the lowest round%' and p.prosrc like '%Prescribed round count mismatch%'
union all select 'EMOM-only completion flags',count(*)::text,'1' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='save_workout_section' and p.prosrc like '%section_row.format is distinct from ''emom''%'
union all select 'Legacy writer rejects numeric-round formats',count(*)::text,'1' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='complete_training_session_internal' and p.prosrc like '%Use per-block logging for numeric round scores%'
union all select 'Private writer helpers exposed',count(*)::text,'0' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('save_training_session_internal','complete_training_session_internal') and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute'))
union all select 'Temporary section-test users',count(*)::text,'0' from auth.users where id in ('00000000-0000-4000-8000-000000000031','00000000-0000-4000-8000-000000000032')
union all select 'Invalid stored round counts',count(*)::text,'0' from public.workout_sections where interval_rounds is not null and (interval_rounds not between 1 and 1440 or format not in ('intervals','tabata','emom') or (format='tabata' and interval_rounds not between 1 and 50));
